import { useEffect, useMemo, useState } from "react";
import { collection, doc, limit, onSnapshot, orderBy, query, serverTimestamp, setDoc } from "firebase/firestore";
import { db } from "../firebase";
import { distanceKm } from "./usePublishedReports";
import { ensureSignedIn } from "./reports";
import { CATEGORIES } from "./labels";

// A report counts toward a beach if it was taken within this distance of it.
export const BEACH_RADIUS_KM = 3;

let loading = null;

// beaches.json is generated by scripts/build-beaches.mjs and only fetched when a map is shown.
export function loadBeaches() {
  loading ??= fetch("/beaches.json")
    .then((res) => {
      if (!res.ok) throw new Error(`beaches.json ${res.status}`);
      return res.json();
    })
    .then(({ countries, beaches }) =>
      beaches.map(([id, name, local, lat, lng, country, desc, wiki]) => ({
        id,
        name,
        local,
        lat,
        lng,
        country: country == null ? null : countries[country],
        desc,
        wiki,
      })),
    )
    .catch((err) => {
      loading = null;
      throw err;
    });
  return loading;
}

export function useBeaches() {
  const [state, setState] = useState({ beaches: null, error: false });
  useEffect(() => {
    let cancelled = false;
    loadBeaches().then(
      (beaches) => !cancelled && setState({ beaches, error: false }),
      () => !cancelled && setState({ beaches: null, error: true }),
    );
    return () => {
      cancelled = true;
    };
  }, []);
  return state;
}

// Buckets beaches into 0.1° cells so finding the nearest one doesn't scan all 15k.
function buildGrid(beaches) {
  const grid = new Map();
  for (const b of beaches) {
    const key = `${Math.floor(b.lat * 10)},${Math.floor(b.lng * 10)}`;
    if (!grid.has(key)) grid.set(key, []);
    grid.get(key).push(b);
  }
  return grid;
}

function nearestBeach(grid, point) {
  const cy = Math.floor(point.lat * 10);
  const cx = Math.floor(point.lng * 10);
  let best = null;
  let bestKm = BEACH_RADIUS_KM;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      for (const b of grid.get(`${cy + dy},${cx + dx}`) ?? []) {
        const km = distanceKm(point, b);
        if (km <= bestKm) {
          best = b;
          bestKm = km;
        }
      }
    }
  }
  return best;
}

// Reports arrive newest first, so each beach's list (and its [0]) stays newest first.
export function useReportsByBeach(beaches, reports) {
  const grid = useMemo(() => (beaches ? buildGrid(beaches) : null), [beaches]);
  return useMemo(() => {
    const byBeach = new Map();
    const unmatched = [];
    if (!grid || !reports) return { byBeach, unmatched, beachOfReport: new Map(), tones: new Map() };
    const beachOfReport = new Map();
    for (const r of reports) {
      const beach = nearestBeach(grid, r.location);
      if (!beach) {
        unmatched.push(r);
        continue;
      }
      beachOfReport.set(r.id, beach.id);
      if (!byBeach.has(beach.id)) byBeach.set(beach.id, []);
      byBeach.get(beach.id).push(r);
    }
    // Each beach is colored by its most recent report.
    const tones = new Map();
    for (const [id, list] of byBeach) tones.set(id, CATEGORIES[list[0].aiAnalysis?.category]?.tone ?? "none");
    return { byBeach, unmatched, beachOfReport, tones };
  }, [grid, reports]);
}

export function googleMapsLinks(beach) {
  // Searching by name opens the place listing (photos, reviews); Taiwan's
  // listings match the Chinese name far more reliably than a romanization.
  // Community beaches often have informal names, so they open at their coordinates.
  const query = isCommunityBeach(beach.id)
    ? `${beach.lat},${beach.lng}`
    : (beach.local ?? [beach.name, beach.country].filter(Boolean).join(", "));
  return {
    place: `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`,
    directions: `https://www.google.com/maps/dir/?api=1&destination=${beach.lat},${beach.lng}`,
  };
}

export const BEACH_KINDS = {
  sand: "Sand",
  pebble: "Pebbles",
  rock: "Rocky shore",
  mixed: "Mixed",
  unknown: "Not sure",
};

const COMMUNITY_PREFIX = "user-";
export const isCommunityBeach = (id) => id.startsWith(COMMUNITY_PREFIX);

const communityQuery = query(collection(db, "beaches"), orderBy("createdAt", "desc"), limit(2000));

function useCommunityBeaches() {
  const [beaches, setBeaches] = useState([]);
  useEffect(
    () =>
      onSnapshot(
        communityQuery,
        (snap) =>
          setBeaches(
            snap.docs.map((d) => {
              const data = d.data();
              return {
                id: `${COMMUNITY_PREFIX}${d.id}`,
                name: data.name,
                local: null,
                lat: data.location.lat,
                lng: data.location.lng,
                country: null,
                desc: null,
                wiki: null,
                kind: data.kind,
                notes: data.notes,
                createdAt: data.createdAt,
              };
            }),
          ),
        (err) => console.error(err),
      ),
    [],
  );
  return beaches;
}

// The listed beaches plus the ones people have added.
export function useAllBeaches() {
  const { beaches, error } = useBeaches();
  const community = useCommunityBeaches();
  const all = useMemo(() => (beaches ? [...beaches, ...community] : null), [beaches, community]);
  return { beaches: all, error };
}

export function findNearby(beaches, point, km = 0.3) {
  let best = null;
  for (const b of beaches ?? []) {
    const d = distanceKm(point, b);
    if (d <= km && (!best || d < best.km)) best = { beach: b, km: d };
  }
  return best;
}

export async function addBeach({ name, kind, notes, location }) {
  const user = await ensureSignedIn();
  const ref = doc(collection(db, "beaches"));
  await setDoc(ref, {
    name: name.trim(),
    kind,
    notes: notes.trim(),
    location: { lat: location.lat, lng: location.lng },
    createdBy: user.uid,
    createdAt: serverTimestamp(),
  });
  return `${COMMUNITY_PREFIX}${ref.id}`;
}
